def MediumAtom.auxSWError (d : MediumAtom) (k q b : ℕ) : ℂ :=
  (∑ n ∈ d.alphaCarrier,
    if Nat.ModEq q n b ∧ Nat.Coprime n k then d.alpha n else 0) -
  (∑ n ∈ d.alphaCarrier,
    if Nat.Coprime n (k * q) then d.alpha n else 0) / (Nat.totient q : ℂ)

def auxiliaryCharacterSum (N : Finset ℕ) (alpha : ℕ → ℂ) (k delta : ℕ)
    (chi : DirichletCharacter ℂ delta) : ℂ :=
  ∑ n ∈ N, if n.Coprime k then alpha n * star (chi (n : ZMod delta)) else 0
